import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long k = Long.parseLong(next());

        final long MOD = 1000000007L;
        int ones = (int) k;
        long[] zero = new long[ones + 1];
        long[] one = new long[ones + 1];
        long[] newZero = new long[ones + 1];
        long[] newOne = new long[ones + 1];
        zero[0] = 1;
        for (long step = 0; step < n; step++) {
            for (int j = 0; j <= ones; j++) {
                newZero[j] = (zero[j] + one[j]) % MOD;
                newOne[j] = j > 0 ? zero[j - 1] : 0;
            }
            long[] swapZero = zero;
            zero = newZero;
            newZero = swapZero;
            long[] swapOne = one;
            one = newOne;
            newOne = swapOne;
        }
        System.out.println((zero[ones] + one[ones]) % MOD);
    }
}
